"""The room-zone finish for the house's shared shell meshes (floor slabs, wall runs, skirting, joinery).

One shell mesh runs through several rooms, and an actor slot holds one material, so the material itself picks the
room: every pixel's surface point (moved 2 cm out along its normal, so each face of a shared wall belongs to the room
it faces) is tested against up to ZONES room boxes; the first box that holds it supplies that room's finish (one of
two scanned sets, an optional printed pattern, tint, roughness, grime). Outside every box the legacy house surface
(ArtDirection09 M_A6_World, copied into the master) is returned untouched, so a room nobody has finished yet looks
exactly as before. Generated HLSL; see zone_finish.hlsl for the single-finish version used by props.
"""
ZONES = 12
ZONE_VECTORS = ['Min', 'Max', 'Tile', 'Tint', 'Rough', 'Grime', 'Mark', 'Pat', 'Opt', 'Extra']
# Min.w = texture set (0 A, 1 B); Max.w = enabled; Extra.w = pattern index (0..2). Others as in zone_finish.hlsl.
SPOTS = 4          # soot spots per material (centre, radius), strength per zone in Mark.x
TEXTURES = [('A_Base', 'C'), ('A_Norm', 'N'), ('A_ARM', 'M'), ('B_Base', 'C'), ('B_Norm', 'N'), ('B_ARM', 'M'),
            ('Pat0', 'C'), ('Pat1', 'C'), ('Pat2', 'C')]


def inputs():
    names = ['LC', 'LR', 'LN', 'LM', 'LS', 'P', 'VN']
    names += [f'Z{i}{v}' for i in range(ZONES) for v in ZONE_VECTORS]
    names += [f'S{i}' for i in range(SPOTS)]
    names += [t for t, _ in TEXTURES]
    return names


def hlsl():
    pick = []
    for i in range(ZONES):
        terms = '; '.join(f'z{v.lower()} += h * Z{i}{v}' for v in ZONE_VECTORS)
        pick.append(f'h = (inside < 0.5 && Z{i}Max.w > 0.5 && all(q >= Z{i}Min.xyz) && all(q <= Z{i}Max.xyz)) ? 1.0 : 0.0; {terms}; inside += h;')
    spots = ' + '.join(f'pow(saturate(1 - distance(P, S{i}.xyz) / max(S{i}.w, 1)), 2)' for i in range(SPOTS))
    body = '\n'.join(pick)
    return f'''// Generated by house_zones.py: room-zone finish over the legacy house surface.
float3 n = normalize(VN);
float3 q = P + n * 2.0;
R = LR; Nrm = LN; M = LM; S = LS;
float4 zmin = 0, zmax = 0, ztile = 0, ztint = 0, zrough = 0, zgrime = 0, zmark = 0, zpat = 0, zopt = 0, zextra = 0;
float inside = 0, h = 0;
{body}
float3 a = abs(n);
float sx = n.x >= 0 ? 1.0 : -1.0, sy = n.y >= 0 ? 1.0 : -1.0;
bool fx = a.x >= a.y && a.x >= a.z, fy = !fx && a.y >= a.z;
float2 uz = zopt.x > 0.5 ? float2(P.y, -P.x) : float2(P.x, P.y);
float2 uv = fx ? float2(-sx * P.y, -P.z) : (fy ? float2(sy * P.x, -P.z) : uz);
float3 tu = fx ? float3(0, -sx, 0) : (fy ? float3(sy, 0, 0) : (zopt.x > 0.5 ? float3(0, 1, 0) : float3(1, 0, 0)));
float3 tv = (fx || fy) ? float3(0, 0, -1) : (zopt.x > 0.5 ? float3(-1, 0, 0) : float3(0, 1, 0));
float2 t1 = uv / max(ztile.xy, 0.001), t2 = uv / max(ztile.zw, 0.001);
float b = saturate(zmin.w);
float3 base = lerp(Texture2DSample(A_Base, A_BaseSampler, t1).rgb, Texture2DSample(B_Base, B_BaseSampler, t1).rgb, b);
float3 arm = lerp(Texture2DSample(A_ARM, A_ARMSampler, t1).rgb, Texture2DSample(B_ARM, B_ARMSampler, t1).rgb, b);
float2 nt = lerp(Texture2DSample(A_Norm, A_NormSampler, t1).rg, Texture2DSample(B_Norm, B_NormSampler, t1).rg, b) * 2 - 1;
float pi = zextra.w;
float3 pc = Texture2DSample(Pat0, Pat0Sampler, t2).rgb * saturate(1 - abs(pi)) + Texture2DSample(Pat1, Pat1Sampler, t2).rgb * saturate(1 - abs(pi - 1))
          + Texture2DSample(Pat2, Pat2Sampler, t2).rgb * saturate(1 - abs(pi - 2));
const float3 L = float3(0.2126, 0.7152, 0.0722);
float3 c = base;
if (zpat.z > 0)
{{
    float paper = dot(base, L) / max(zpat.x, 0.02);
    pc = lerp(pc, dot(pc, L).xxx, zpat.y) * lerp(float3(1, 1, 1), float3(1.0, 0.86, 0.62), zpat.w);
    c = lerp(base, pc * paper, zpat.z);
}}
c = lerp(dot(c, L).xxx, c, ztint.w) * ztint.rgb;
c *= lerp(1.0, arm.r, zopt.w);
float dirt = zgrime.y * (1 - smoothstep(0, max(zgrime.x, 1), P.z - zmin.z));
float soot = saturate(zgrime.w * smoothstep(zgrime.z, zmax.z, P.z) + zmark.x * ({spots}));
float edge = min(min(P.x - zmin.x, zmax.x - P.x), min(P.y - zmin.y, zmax.y - P.y));
float band = zmark.y > 0 ? 1 - smoothstep(zmark.y * 0.85, zmark.y * 1.15, edge) : 0;
c *= (1 - dirt) * (1 - soot) * (1 - zmark.z * band);
float lift = zextra.y * (dot(base, L) / max(zextra.z, 0.001) - 1);
float r = saturate(arm.g * zrough.x + zrough.y + lift + 0.25 * dirt + 0.2 * soot - zmark.w * band);
float3 g = nt.x * tu + nt.y * tv;
g -= n * dot(g, n);
float3 nz = normalize(n + g * zopt.z);
R = lerp(LR, r, inside);
Nrm = normalize(lerp(LN, nz, inside));
M = lerp(LM, saturate(arm.b * zrough.z + zextra.x), inside);
S = lerp(LS, zrough.w, inside);
return lerp(LC, c, inside);
'''
